412	// registerConnection holds onto conn so it can be closed in the event
413	// of a server shutdown. This is useful because hijacked connections or
414	// connections dialed to backends don't close when server is shut down.
415	// The caller should call the returned delete() function when the
416	// connection is done to remove it from memory.
417	func (h *Handler) registerConnection(conn io.ReadWriteCloser, gracefulClose func() error) (del func()) {
418		h.connectionsMu.Lock()
419		h.connections[conn] = openConnection{conn, gracefulClose}
420		h.connectionsMu.Unlock()
421		return func() {
422			h.connectionsMu.Lock()
423			delete(h.connections, conn)
424			// if there is no connection left before the connections close timer fires
425			if len(h.connections) == 0 && h.connectionsCloseTimer != nil {
426				// we release the timer that holds the reference to Handler
427				if (*h.connectionsCloseTimer).Stop() {
428					h.logger.Debug("stopped streaming connections close timer - all connections are already closed")
429				}
430				h.connectionsCloseTimer = nil
431			}
432			h.connectionsMu.Unlock()
433		}
434	}
435	
436	// closeConnections immediately closes all hijacked connections (both to client and backend).
437	func (h *Handler) closeConnections() error {
438		var err error
439		h.connectionsMu.Lock()
440		defer h.connectionsMu.Unlock()
441	
442		for _, oc := range h.connections {
443			if oc.gracefulClose != nil {
444				// this is potentially blocking while we have the lock on the connections
445				// map, but that should be OK since the server has in theory shut down
446				// and we are no longer using the connections map
447				gracefulErr := oc.gracefulClose()
448				if gracefulErr != nil && err == nil {
449					err = gracefulErr
450				}
451			}
452			closeErr := oc.conn.Close()
453			if closeErr != nil && err == nil {
454				err = closeErr
455			}
456		}
457		return err
458	}
459	
460	// cleanupConnections closes hijacked connections.
461	// Depending on the value of StreamCloseDelay it does that either immediately
462	// or sets up a timer that will do that later.
463	func (h *Handler) cleanupConnections() error {
464		if h.StreamCloseDelay == 0 {
465			return h.closeConnections()
466		}
467	
468		h.connectionsMu.Lock()
469		defer h.connectionsMu.Unlock()
470		// the handler is shut down, no new connection can appear,
471		// so we can skip setting up the timer when there are no connections
472		if len(h.connections) > 0 {
473			delay := time.Duration(h.StreamCloseDelay)
474			h.connectionsCloseTimer = time.AfterFunc(delay, func() {
475				if c := h.logger.Check(zapcore.DebugLevel, "closing streaming connections after delay"); c != nil {
476					c.Write(zap.Duration("delay", delay))
477				}
478				err := h.closeConnections()
479				if err != nil {
480					if c := h.logger.Check(zapcore.ErrorLevel, "failed to closed connections after delay"); c != nil {
481						c.Write(
482							zap.Error(err),
483							zap.Duration("delay", delay),
484						)
485					}
486				}
487			})
488		}
489		return nil
490	}
491	
492	// writeCloseControl sends a best-effort Close control message to the given
493	// WebSocket connection. Thanks to @pascaldekloe who provided inspiration
494	// from his simple implementation of this I was able to learn from at:
495	// github.com/pascaldekloe/websocket. Further work for handling masking
496	// taken from github.com/gorilla/websocket.
497	func writeCloseControl(conn io.Writer, isClient bool) error {
498		// Sources:
499		// https://github.com/pascaldekloe/websocket/blob/32050af67a5d/websocket.go#L119
500		// https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L413
501	
502		// For now, we're not using a reason. We might later, though.
503		// The code handling the reason is left in
504		var reason string // max 123 bytes (control frame payload limit is 125; status code takes 2)
505	
506		const closeMessage = 8
507		const finalBit = 1 << 7 // Frame header byte 0 bits from Section 5.2 of RFC 6455
508		const maskBit = 1 << 7  // Frame header byte 1 bits from Section 5.2 of RFC 6455
509		const goingAwayUpper uint8 = 1001 >> 8
510		const goingAwayLower uint8 = 1001 & 0xff
511	
512		b0 := byte(closeMessage) | finalBit
513		b1 := byte(len(reason) + 2)
514		if isClient {
515			b1 |= maskBit
516		}
517	
518		buf := make([]byte, 0, 127)
519		buf = append(buf, b0, b1)
520		msgLength := 4 + len(reason)

